    data["title"] = "2-Ⅳ-11：從簡易短劇的角色、舞台指示與結局理解情節"
    data["content"] = {"summary": "短劇同時用對話和舞台指示說故事：角色說出目標與關係，括號中的動作、燈光、聲音和道具推動事件，衝突在選擇或協商中改變，結局則顯示問題如何被處理。本課以尋找走失小狗、故事結束、地圖分工、帽子衝突、鬧鐘道具、灑出的顏料、暖座位、思考停頓、借書歸還與暴風雨改場等原創短劇，練習用事件線理解誰要做什麼、下一步發生什麼及舞台選擇如何影響觀眾。", "sections": [{"heading": "角色目標讓對話有方向", "body": "Nina holds a map and says I will find the missing puppy，角色是尋找者，目標是找到小狗；Lia 分配畫地圖與寫標籤，顯示她在有限時間內組織合作。先圈角色、動作和目標，再判斷台詞是在介紹、計畫、衝突還是解決。"}, {"heading": "舞台指示是情節證據", "body": "[The lights become dim.]、[A storm sound begins.]、[Mia enters, sees the spilled paint …] 都不是可有可無的裝飾；它們標示時間、氣氛、危險或下一個動作。回答 immediately after 時要照指示順序，不可跳到後來的結果。"}, {"heading": "道具和停頓替觀眾傳遞資訊", "body": "響起的鬧鐘讓演員跑向門口，成為觸發情節的道具；問題後的 pause 則留出思考時間，使觀眾注意線索。分析道具時問它何時出現、引發誰的行動、結尾是否再次回收，不只描述它放在哪裡。"}, {"heading": "結局顯示衝突或關係的變化", "body": "紅藍帽子的協商把兩人的需求分開，借書歸還並道謝則顯示責任被完成、關係得到修復。暴風雨中把戶外演出移到室內，顯示角色依安全條件改變計畫。結局摘要要連回起始問題與中間選擇，不能只抄最後一句。"}]}
    data["studyHighlights"] = ["從角色、動作與台詞辨認目標、分工、衝突與情節方向。", "依舞台指示、燈光、聲音與動作的順序定位事件。", "分析道具如何觸發行動、停頓如何引導觀眾理解。", "用起始問題、中間選擇與結局變化概括短劇結果。"]
    data["teaching"] = {"body": [{"id": "hook", "phase": "hook", "heading": "括號裡的字也在說故事嗎？", "body": "播放一段完全自編的無對話短劇，只演燈光變暗、鬧鐘響、角色跑門口三個舞台指示，讓學生先猜發生什麼。再加入台詞比較，指出舞台指示如何補上時間、觸發和情緒，並非排演時可以忽略的備註。"}, {"id": "explain", "phase": "explain", "heading": "短劇六格事件卡", "body": "建立 Role、Goal、Stage clue、Action、Conflict、Outcome 六格。先標角色和目標，再按舞台指示與對話排動作，找出需求衝突，最後用結局檢查誰改變了計畫或完成了責任；每一格都要能回指腳本位置。"}, {"id": "worked-example", "phase": "worked-example", "heading": "從帽子衝突讀出協商", "body": "以 Ben 想要紅帽、Kai 需要紅帽演角色、導演安排藍帽和紅帽分用的原創片段示範。先列兩個需求，再指出解決方案如何分配道具；答案不是誰贏了，而是衝突如何透過安排讓兩人都能完成角色。"}, {"id": "guided-practice", "phase": "guided-practice", "heading": "照舞台指示找下一步", "body": "給 Mia 看見灑漆、呼叫抹布、清理地板的腳本卡，學生先遮住後兩步，只回答 immediately after；再打開檢查。換成暴風雨聲、搬椅子與燈光變化，讓同伴指出哪個聲音或動作改變了情節方向。"}, {"id": "transfer", "phase": "transfer", "heading": "為不同觀眾改寫演出提示", "body": "輪換小狗、借書、暖座位、室內演出、鬧鐘與地圖分工短劇。學生為低年級觀眾、沒有字幕的觀眾或只看舞台不聽台詞的觀眾，選擇要加強動作、道具、停頓或旁白，並說明哪些情節證據不能刪掉。"}, {"id": "reflect", "phase": "reflect", "heading": "我有把結局連回問題嗎？", "body": "回看摘要，標出 opening problem、choice、stage evidence、outcome 和 relationship change。若只說角色最後做了什麼，補回衝突與原因；若把演員想像的內心當腳本事實，改成由台詞或舞台指示支持的保留推論。"}], "summary": ["以 Role、Goal、Stage clue、Action、Conflict、Outcome 六格讀短劇。", "按照舞台指示與對話順序判斷下一個事件。", "把道具、停頓、燈光與聲音連到觀眾理解和角色行動。", "用問題、選擇與結局變化概括短劇而不只抄最後一句。"], "exitCheck": [{"prompt": "舞台指示如何成為情節證據？", "expectedEvidence": "能指出燈光、聲音、動作或道具標示時間、氣氛、觸發與下一步，並依順序回答。"}, {"prompt": "短劇中的衝突如何判斷已被處理？", "expectedEvidence": "能比較角色需求、協商或選擇與結局，說明計畫、責任或關係發生何種變化。"}, {"prompt": "如何讓短劇摘要不只重述最後一句？", "expectedEvidence": "能保留起始問題、中間行動或舞台證據，以及結局如何回應問題。"}]}
    data["interactive"] = {"type": "guided-choice", "goal": "從短劇角色、目標、舞台指示、道具、衝突與結局理解情節並選擇下一個事件。", "scenario": "學生擔任校園短劇導演助理，要替演員排出動作、處理道具衝突，並為觀眾寫出有證據的情節摘要。", "variables": [{"symbol": "r", "meaning": "角色、關係與目標"}, {"symbol": "s", "meaning": "舞台指示、道具、聲音與動作順序"}, {"symbol": "o", "meaning": "衝突解決、結局與觀眾理解"}], "steps": [{"id": "step-1", "prompt": "Nina holds a map and says, 'I will find the missing puppy.' Which role and goal are clear?", "options": ["Nina is the finder, and her goal is to find the puppy.", "Nina is the puppy, and her goal is to close the theater.", "Nina is the audience, and her goal is to sell a red hat."], "answer": "A", "feedback": "A connects the stage action and line with Nina's role and stated goal without adding events."}, {"id": "step-2", "prompt": "Mia enters, sees spilled paint, calls for a cloth, and cleans the floor. What happens immediately after she sees the paint?", "options": ["She calls for a cloth.", "She finishes cleaning the floor.", "She returns a borrowed book."], "answer": "A", "feedback": "A follows the script order; cleaning happens later and the book belongs to a different scene."}, {"id": "step-3", "prompt": "The director says, 'Pause after the question so the audience can think.' Why is the pause used?", "options": ["It gives the audience time to consider the question.", "It tells the actors to end every scene immediately.", "It hides which character is speaking."], "answer": "A", "feedback": "A states the director's purpose and connects the pause to audience understanding."}]}
